import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { kvGet, kvSet } from "../core/db.js";

// Incremental preflight checks only changed ArkTS sources. Files with errors are rechecked.
const skip = new Set(["node_modules", "oh_modules", "build", ".hvigor", ".git", ".idea", ".preview", ".arkpilot", "libs"]);
/** Generated by hvigor on every build, or build scripts: never application code to check. */
const generated = /(^|\/)(BuildProfile\.ets|hvigorfile\.ts|hvigorconfig\.ts)$/;
export function trackedSource(rel: string) {
  return /\.(ets|ts)$/.test(rel) && !rel.endsWith(".d.ts") && !generated.test(rel)
    && !rel.split("/").some((part) => skip.has(part) || part.startsWith("."));
}
export type SourceSnapshot = Record<string, string>;

// Keep the size and digest in the same fields as older "mtime,ctime:size:digest" snapshots.
export function snapshotFile(file: string, buffer: Buffer) {
  const hash = crypto.createHash("sha1");
  const fd = fs.openSync(file, "r");
  let size = 0;
  try {
    for (let n; (n = fs.readSync(fd, buffer)) > 0;) {
      hash.update(buffer.subarray(0, n));
      size += n;
    }
  } finally { fs.closeSync(fd); }
  return `content:${size}:${hash.digest("hex").slice(0, 16)}`;
}
const content = (entry: string | undefined) => entry?.split(":")[2];

/** Content identity, independent of traversal order and build-generated timestamp changes. */
export function sourceIdentity(snapshot: SourceSnapshot) {
  return crypto.createHash("sha256").update(JSON.stringify(Object.keys(snapshot).sort().map((file) => [file, content(snapshot[file])]))).digest("hex");
}

// Filesystems can give distinct same-size writes identical timestamps. Read current bytes.
export function snapshotSources(root: string): SourceSnapshot {
  const buffer = Buffer.allocUnsafe(64 * 1024);
  const out: SourceSnapshot = {};
  const base = path.resolve(root);
  const stack = [base];
  while (stack.length) {
    const dir = stack.pop()!;
    let entries: fs.Dirent[];
    entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const e of entries) {
      if (skip.has(e.name) || e.name.startsWith(".")) continue;
      const full = path.join(dir, e.name);
      if (e.isDirectory()) { stack.push(full); continue; }
      const rel = path.relative(base, full).replaceAll("\\", "/");
      if (!trackedSource(rel)) continue;
      out[rel] = snapshotFile(full, buffer);
    }
  }
  return out;
}

/** Files added or whose content changed between two snapshots (deleted files need no check). Pure. */
export function diffSources(previous: SourceSnapshot, current: SourceSnapshot) {
  return Object.keys(current).filter((f) => content(previous[f]) !== content(current[f])).sort();
}

const key = (root: string) => `preflight:${path.resolve(root)}`;

/**
 * files=undefined: no baseline yet (first preflight) or too many edits to be worth scoping -> whole project.
 * files=[]: nothing changed since the last preflight.
 */
export async function changedSources(root: string, maxFiles = 200) {
  const raw = await kvGet(key(root)).catch(() => undefined);
  const previous = raw ? (JSON.parse(raw) as SourceSnapshot) : undefined;
  const snapshot = snapshotSources(root);
  if (!previous) return { files: undefined, snapshot };
  const changed = diffSources(previous, snapshot);
  if (changed.length > maxFiles) return { files: undefined, snapshot };
  // A changed export breaks its importers although they did not change: check those too.
  const importers = importersOf(root, changed, Object.keys(snapshot), 50);
  return { files: [...new Set([...changed, ...importers])].sort(), snapshot, ...(importers.length ? { importers: importers.length } : {}) };
}

/**
 * Files that import one of `changed` through a relative path ('./Helper', '../model/Item'): the
 * dependents whose type check can change. Module imports (@ohos/..., HAR names) are not followed;
 * those importers are still checked by hvigor at build time. Bounded to `limit` files. Pure-ish (reads files).
 */
export function importersOf(root: string, changed: string[], all: string[], limit = 50) {
  if (!changed.length) return [];
  const targets = new Set(changed.map((f) => f.replace(/\.(ets|ts)$/, "")));
  const out: string[] = [];
  const re = /\bfrom\s+['"](\.{1,2}\/[^'"]+)['"]|\bimport\s*\(\s*['"](\.{1,2}\/[^'"]+)['"]\s*\)/g;
  for (const file of all) {
    if (targets.has(file.replace(/\.(ets|ts)$/, "")) || out.length >= limit) continue;
    let text: string;
    try { text = fs.readFileSync(path.join(root, file), "utf8"); } catch { continue; }
    for (const m of text.matchAll(re)) {
      const spec = (m[1] ?? m[2])!;
      const resolved = path.posix.normalize(path.posix.join(path.posix.dirname(file), spec)).replace(/\.(ets|ts)$/, "");
      if (targets.has(resolved) || targets.has(`${resolved}/Index`) || targets.has(`${resolved}/index`)) { out.push(file); break; }
    }
  }
  return out;
}

/** Remember the checked state; files with errors are left out so the next preflight checks them again. */
export async function rememberSources(root: string, snapshot: SourceSnapshot, failing: string[] = []) {
  const kept = { ...snapshot };
  for (const f of failing) delete kept[f.replaceAll("\\", "/")];
  await kvSet(key(root), JSON.stringify(kept)).catch(() => undefined);
}
